final notifications = FlutterLocalNotificationsPlugin();
String newId() => DateTime.now().microsecondsSinceEpoch.toString();
String jDate(DateTime d) { final j = Gregorian.fromDateTime(d).toJalali(); return '${j.year}/${j.month.toString().padLeft(2, '0')}/${j.day.toString().padLeft(2, '0')}'; }
String hTime(DateTime d) => '${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';
bool dayEq(DateTime a, DateTime b) => a.year == b.year && a.month == b.month && a.day == b.day;

Future<DateTime?> pickJDateTime(BuildContext context, DateTime initial, {bool allowPast = true}) async {
  final min = allowPast ? Jalali(1380, 1, 1) : Gregorian.fromDateTime(DateTime.now()).toJalali();
  final p = await showJalaliDatePicker(context, initialDate: Gregorian.fromDateTime(initial).toJalali(), firstDate: min, lastDate: Jalali(1450, 12, 29), textDirection: TextDirection.rtl);
  if (p == null) return null;
  final g = p.toGregorian();
  final t = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(initial));
  if (t == null) return null;
  return DateTime(g.year, g.month, g.day, t.hour, t.minute);
}

class FollowUp {
  String id, text; DateTime at; DateTime? reminder;
  FollowUp({required this.id, required this.text, required this.at, this.reminder});
  Map<String,dynamic> toJson()=>{'id':id,'text':text,'at':at.toIso8601String(),'reminder':reminder?.toIso8601String()};
  factory FollowUp.fromJson(Map<String,dynamic> x)=>FollowUp(id:'${x['id']??newId()}',text:'${x['text']??''}',at:DateTime.tryParse('${x['at']}')??DateTime.now(),reminder:x['reminder']==null?null:DateTime.tryParse('${x['reminder']}'));
}

class ArvinItem {
  String id,title,note,category; DateTime date; DateTime? reminder; bool task,archived,trash; List<String> tags,checklist; List<bool> checked; List<FollowUp> followUps;
  ArvinItem({required this.id,required this.title,required this.note,required this.category,required this.date,required this.task,required this.tags,required this.checklist,required this.checked,required this.followUps,this.reminder,this.archived=false,this.trash=false});
  Map<String,dynamic> toJson()=>{'id':id,'title':title,'note':note,'category':category,'date':date.toIso8601String(),'reminder':reminder?.toIso8601String(),'task':task,'archived':archived,'trash':trash,'tags':tags,'checklist':checklist,'checked':checked,'followUps':followUps.map((e)=>e.toJson()).toList()};
  factory ArvinItem.fromJson(Map<String,dynamic> x){final cl=List<String>.from(x['checklist']??[]);final ch=List<bool>.from(x['checked']??[]);while(ch.length<cl.length){ch.add(false);}return ArvinItem(id:'${x['id']??newId()}',title:'${x['title']??''}',note:'${x['note']??x['description']??''}',category:'${x['category']??x['cat']??'عمومی'}',date:DateTime.tryParse('${x['date']}')??DateTime.now(),reminder:x['reminder']==null?null:DateTime.tryParse('${x['reminder']}'),task:x['task']??false,archived:x['archived']??x['arch']??false,trash:x['trash']??x['trashed']??false,tags:List<String>.from(x['tags']??[]),checklist:cl,checked:ch,followUps:(x['followUps']??x['fs']??[]).map((e)=>FollowUp.fromJson(Map<String,dynamic>.from(e))).toList());}
}

Future<void> initNotifications() async {tz.initializeTimeZones();tz.setLocalLocation(tz.getLocation('Asia/Tehran'));await notifications.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher')));await notifications.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission();}
Future<void> scheduleReminder(int id,String title,String body,DateTime when) async {if(!when.isAfter(DateTime.now()))return;const a=AndroidNotificationDetails('arvin','یادآوری‌های آروین',channelDescription:'یادآوری کارها و پیگیری‌ها',importance:Importance.max,priority:Priority.high);await notifications.zonedSchedule(id,title,body,tz.TZDateTime.from(when,tz.local),const NotificationDetails(android:a),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle);}

Future<void> main() async {WidgetsFlutterBinding.ensureInitialized();await initNotifications();runApp(const ArvinApp());}
class ArvinApp extends StatefulWidget{const ArvinApp({super.key});@override State<ArvinApp>createState()=>_ArvinAppState();}
class _ArvinAppState extends State<ArvinApp>{String font='Vazirmatn';bool dark=false;@override void initState(){super.initState();_load();}Future<void>_load()async{final p=await SharedPreferences.getInstance();if(!mounted)return;setState((){font=p.getString('font')??'Vazirmatn';dark=p.getBool('dark')??false;});}Future<void>setFont(String v)async{final p=await SharedPreferences.getInstance();await p.setString('font',v);if(mounted)setState(()=>font=v);}Future<void>setDark(bool v)async{final p=await SharedPreferences.getInstance();await p.setBool('dark',v);if(mounted)setState(()=>dark=v);}@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'آروین',theme:ThemeData(useMaterial3:true,fontFamily:font),darkTheme:ThemeData(useMaterial3:true,fontFamily:font,brightness:Brightness.dark),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Directionality(textDirection:TextDirection.rtl,child:Home(font:font,dark:dark,onFont:setFont,onDark:setDark)));}

class Home extends StatefulWidget{final String font;final bool dark;final Future<void>Function(String)onFont;final Future<void>Function(bool)onDark;const Home({super.key,required this.font,required this.dark,required this.onFont,required this.onDark});@override State<Home>createState()=>_HomeState();}
class _HomeState extends State<Home>{
List<ArvinItem>items=[];List<String>categories=['عمومی'],tags=[];String categoryFilter='همه',timeFilter='همه',sort='آخرین وارده';bool reverse=false,multi=false;final selected=<String>{};String swipeLeft='سطل زباله',swipeRight='امروز';bool loading=true;
@override void initState(){super.initState();_load();}
Future<void>_load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('items')??p.getString('arvin_items');if(raw!=null)items=(jsonDecode(raw)as List).map((e)=>ArvinItem.fromJson(Map<String,dynamic>.from(e))).toList();categories=p.getStringList('cats')??p.getStringList('arvin_categories')??['عمومی'];if(!categories.contains('عمومی'))categories.insert(0,'عمومی');tags=p.getStringList('tags')??[];categoryFilter=p.getString('catFilter')??'همه';timeFilter=p.getString('timeFilter')??'همه';swipeLeft=p.getString('swipeLeft')??'سطل زباله';swipeRight=p.getString('swipeRight')??'امروز';for(final x in items){if(x.reminder!=null)scheduleReminder(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.reminder!);for(final f in x.followUps){if(f.reminder!=null)scheduleReminder(('f'+f.id).hashCode,'یادآوری پیگیری: ${x.title}',f.text.isEmpty?'زمان پیگیری فرا رسید':f.text,f.reminder!);}}if(mounted)setState(()=>loading=false);}
Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('items',jsonEncode(items.map((e)=>e.toJson()).toList()));await p.setStringList('cats',categories);await p.setStringList('tags',tags);await p.setString('catFilter',categoryFilter);await p.setString('timeFilter',timeFilter);await p.setString('swipeLeft',swipeLeft);await p.setString('swipeRight',swipeRight);}
List<ArvinItem>get visible{final now=DateTime.now();var r=items.where((x)=>!x.trash);r=r.where((x){if(timeFilter=='بایگانی')return x.archived;if(x.archived)return false;if(timeFilter=='امروز')return dayEq(x.date,now);if(timeFilter=='آینده')return x.date.isAfter(now);if(timeFilter=='عقب‌افتاده')return x.date.isBefore(now)&&!dayEq(x.date,now);if(timeFilter=='یادداشت‌ها')return !x.task;if(timeFilter=='کارها')return x.task;return true;});r=r.where((x)=>categoryFilter=='همه'||x.category==categoryFilter);final list=r.toList();list.sort((a,b){int c;if(sort=='عنوان')c=a.title.compareTo(b.title);else if(sort=='تاریخ')c=a.date.compareTo(b.date);else{final ad=a.followUps.isEmpty?a.date:a.followUps.last.at;final bd=b.followUps.isEmpty?b.date:b.followUps.last.at;c=ad.compareTo(bd);}return reverse?c:-c;});return list;}
Future<void>editItem({ArvinItem?old,bool task=false})async{final x=await showModalBottomSheet<ArvinItem>(context:context,isScrollControlled:true,builder:(_)=>Editor(old:old,task:old?.task??task,categories:categories,tags:tags));if(x==null)return;if(old==null)items.add(x);else{final i=items.indexWhere((e)=>e.id==old.id);if(i>=0)items[i]=x;}await save();if(x.reminder!=null)await scheduleReminder(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.reminder!);if(mounted)setState((){});}
Future<void>addFollowUp(ArvinItem item,{FollowUp?old})async{final f=await showDialog<FollowUp>(context:context,builder:(_)=>FollowEditor(old:old));if(f==null)return;if(old==null)item.followUps.add(f);else{final i=item.followUps.indexOf(old);if(i>=0)item.followUps[i]=f;}await save();if(f.reminder!=null)await scheduleReminder(('f'+f.id).hashCode,'یادآوری پیگیری: ${item.title}',f.text.isEmpty?'زمان پیگیری فرا رسید':f.text,f.reminder!);if(mounted)setState((){});}
Future<void>deleteFollowUp(ArvinItem item,FollowUp f)async{item.followUps.remove(f);await save();if(mounted)setState((){});}
Future<void>exportItemPdf(ArvinItem x)async{final d=pw.Document();d.addPage(pw.MultiPage(build:(_)=>[pw.Text(x.title),pw.Text('دسته: ${x.category}'),pw.Text('تاریخ: ${jDate(x.date)} ${hTime(x.date)}'),pw.Text(x.note),...x.followUps.map((f)=>pw.Text('${jDate(f.at)} ${hTime(f.at)}  ${f.text}'))]));await Printing.sharePdf(bytes:await d.save(),filename:'arvin_${x.id}.pdf');}
