Future<void>backup()async{final dir=await getApplicationDocumentsDirectory();final f=File('${dir.path}/arvin_backup.json');await f.writeAsString(jsonEncode({'items':items.map((e)=>e.toJson()).toList(),'cats':categories,'tags':tags}));await Share.shareXFiles([XFile(f.path)],text:'پشتیبان آروین');}
Future<void>restore()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(r==null||r.files.single.bytes==null)return;final m=jsonDecode(utf8.decode(r.files.single.bytes!))as Map<String,dynamic>;items=(m['items']as List).map((e)=>ArvinItem.fromJson(Map<String,dynamic>.from(e))).toList();categories=List<String>.from(m['cats']??['عمومی']);tags=List<String>.from(m['tags']??[]);if(!categories.contains('عمومی'))categories.insert(0,'عمومی');await save();if(mounted)setState((){});}
