Future<void>applySwipe(ArvinItem x,String action)async{if(action=='امروز')x.date=DateTime.now();else if(action=='بایگانی')x.archived=true;else if(action=='سطل زباله')x.trash=true;else if(action=='پیگیری'&&x.task)await addFollowUp(x);else if(action=='ویرایش')await editItem(old:x);else if(action=='اشتراک‌گذاری')await exportItemPdf(x);await save();if(mounted)setState((){});}
