class SettingsPage extends StatelessWidget{final String font;final bool dark;final Future<void>Function(String)onFont;final Future<void>Function(bool)onDark;final String left,right;final Future<void>Function(String,String)onSwipe;const SettingsPage({super.key,required this.font,required this.dark,required this.onFont,required this.onDark,required this.left,required this.right,required this.onSwipe});Future<String?>choose(BuildContext c)=>showDialog<String>(context:c,builder:(x)=>SimpleDialog(title:const Text('عملیات Swipe'),children:['هیچ‌کاری','امروز','بایگانی','سطل زباله','پیگیری','ویرایش','اشتراک‌گذاری'].map((a)=>SimpleDialogOption(onPressed:()=>Navigator.pop(x,a),child:Text(a))).toList()));Future<void>pick(BuildContext c,bool isLeft)async{final v=await choose(c);if(v==null)return;await onSwipe(isLeft?v:left,isLeft?right:v);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تنظیمات')),body:ListView(padding:const EdgeInsets.all(16),children:[SwitchListTile(title:const Text('حالت تاریک'),value:dark,onChanged:onDark),ListTile(title:Text('فونت اصلی: $font'),onTap:()=>onFont('Vazirmatn')),ListTile(title:Text('کشیدن به چپ: $left'),onTap:()=>pick(c,true)),ListTile(title:Text('کشیدن به راست: $right'),onTap:()=>pick(c,false))]));}
